package com.apixenglish.center.modules.learningreport.entity;
import com.apixenglish.center.common.domain.SoftDeleteEntity;import com.apixenglish.center.modules.classmanagement.entity.Clazz;import com.apixenglish.center.modules.employee.entity.Employee;import com.apixenglish.center.modules.student.entity.Student;import jakarta.persistence.*;import lombok.*;import java.time.*;
@Entity @Table(name="student_learning_reports") @Getter @Setter @Builder @NoArgsConstructor @AllArgsConstructor public class StudentLearningReport extends SoftDeleteEntity{
 @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="student_id",nullable=false) private Student student;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="class_id",nullable=false) private Clazz clazz;
 @Column(name="report_type",nullable=false) private String reportType;@Column(name="period_start",nullable=false) private LocalDate periodStart;@Column(name="period_end",nullable=false) private LocalDate periodEnd;
 @Column(name="learning_summary",nullable=false) private String learningSummary;@Column(name="attitude_summary") private String attitudeSummary;@Column(name="improvement_notes") private String improvementNotes;private String recommendation;@Column(name="internal_note") private String internalNote;
 @Enumerated(EnumType.STRING) @Column(nullable=false) private LearningReportStatus status;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="prepared_by",nullable=false) private Employee preparedBy;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="approved_by") private Employee approvedBy;@Column(name="approved_at") private Instant approvedAt;@Column(name="rejection_reason") private String rejectionReason;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="delivered_by") private Employee deliveredBy;@Column(name="delivered_at") private Instant deliveredAt;
}
